using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class AndroidResearchLaunchPreviewFileStoreTests{[Fact]public void Preview_round_trips_without_order_authority(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var path=Path.Combine(root,"preview.json");var value=new AndroidResearchLaunchPreview("P","D","DS","SS",true,"Ready",false);var store=new AndroidResearchLaunchPreviewFileStore(path);store.Save(value);Assert.Equal(value,store.Load());}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}}
